// Spec 015 (TICKET005): single source of truth for the per-agent loop prompts.
//
// The canonical templates live in prompts/shared/. Each agent's
// prompts/<agent>/LOOP.md and SPRINT-ROLLOVER.md is generated byte-identical
// from them. The per-agent files MUST stay on disk: scripts/autonomy-loop.ps1
// reads prompts/<agent>/LOOP.md at dispatch (New-LoopPromptText, throws if
// missing) and substitutes {AGENT} at runtime, so the canonical keeps the
// literal {AGENT} token and this generator only fans the bytes out.
//
// Workflow: edit prompts/shared/<template>, run `node scripts/generate-agent-prompts.mjs`,
// commit. The vitest drift test (tests/prompts/agent-prompts.test.ts) and
// `--check` mode both fail if a per-agent copy diverges from its canonical.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const promptsDir = join(repoRoot, "prompts");
const sharedDir = join(promptsDir, "shared");

// Agents that the runner dispatches via prompts/<agent>/LOOP.md. Keep in sync
// with the prompt directories the dispatcher constructs.
export const AGENTS = ["claude", "codex", "gemini", "grok", "meta"];
export const TEMPLATES = ["LOOP.md", "SPRINT-ROLLOVER.md"];

// Returns the full set of generated outputs without writing anything. The
// canonical Buffer is read once per template and shared across agents because
// every agent receives identical bytes.
export function plan() {
  const outputs = [];
  for (const template of TEMPLATES) {
    const content = readFileSync(join(sharedDir, template));
    for (const agent of AGENTS) {
      outputs.push({
        agent,
        template,
        target: join(promptsDir, agent, template),
        content
      });
    }
  }
  return outputs;
}

// Writes every per-agent file from its canonical template. Idempotent.
export function writeAll() {
  const outputs = plan();
  for (const out of outputs) {
    writeFileSync(out.target, out.content);
  }
  return outputs;
}

// Returns drift entries: per-agent files that are missing or differ byte-for-byte
// from their canonical template. Empty array means everything is in sync.
export function check() {
  const drift = [];
  for (const out of plan()) {
    let actual;
    try {
      actual = readFileSync(out.target);
    } catch {
      drift.push({ agent: out.agent, template: out.template, reason: "missing" });
      continue;
    }
    if (!actual.equals(out.content)) {
      drift.push({ agent: out.agent, template: out.template, reason: "content-mismatch" });
    }
  }
  return drift;
}

const invokedDirectly =
  process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;

if (invokedDirectly) {
  if (process.argv[2] === "--check") {
    const drift = check();
    if (drift.length > 0) {
      for (const entry of drift) {
        console.error(`drift (${entry.reason}): prompts/${entry.agent}/${entry.template}`);
      }
      console.error("Run `node scripts/generate-agent-prompts.mjs` to regenerate from prompts/shared/.");
      process.exit(1);
    }
    console.log(`Agent prompts in sync: ${AGENTS.length} agents x ${TEMPLATES.length} templates.`);
  } else {
    const outputs = writeAll();
    console.log(`Generated ${outputs.length} agent prompt file(s) from prompts/shared/.`);
  }
}
